export function fibonacciPoints(count){return Array.from({length:count},(_,i)=>{const y=1-2*(i+.5)/count,r=Math.sqrt(1-y*y),a=i*Math.PI*(3-Math.sqrt(5));return [Math.cos(a)*r,y,Math.sin(a)*r]})}
export function rotatePoint([x,y,z],yaw,pitch){const a=x*Math.cos(yaw)+z*Math.sin(yaw),b=z*Math.cos(yaw)-x*Math.sin(yaw);return [a,y*Math.cos(pitch)-b*Math.sin(pitch),y*Math.sin(pitch)+b*Math.cos(pitch)]}
export function projectPoint(point,width,height,radius){const [x,y,z]=point,scale=3.7/(3.7-z);return {x:width/2+x*radius*scale,y:height/2+y*radius*scale,z,scale}}
export function arcPoint(a,b,t){const v=a.map((x,i)=>x*(1-t)+b[i]*t),length=Math.hypot(...v);return length<1e-8?a.map(x=>x*1.015):v.map(x=>x/length*1.015)}
export function partForPage(manifest,page){const n=Math.max(1,Math.min(manifest.totalPages,Math.trunc(Number(page)||1)));const part=manifest.parts.find(p=>n>=p.start&&n<=p.end);if(!part)throw Error('Missing textbook page');return {part,page:n,localPage:n-part.start+1}}
// Stable card slots keep reaction text readable while their surface anchors rotate.
export function reactionCallouts(count,width,height){const rows=Math.ceil(count/2),cardWidth=Math.min(218,width*(width<650?.34:.32)),cardHeight=width<650?100:88,gap=width<650?10:17,extent=rows*cardHeight+(rows-1)*gap,top=Math.max(42,(height-extent)/2);return Array.from({length:count},(_,i)=>{const side=i<rows?-1:1,row=i%rows;return {x:side<0?cardWidth/2+10:width-cardWidth/2-10,y:top+row*(cardHeight+gap)+cardHeight/2,width:cardWidth,height:cardHeight,side}})}
export function particleSurface([x,y,z],time){const wave=Math.sin(y*6+time*1.1)+.45*Math.sin(x*5-z*4-time*.8),r=1+wave*.038;return [x*r,y*(1+.025*Math.cos(z*6+time)),z*r]}
export function dragRotation(yaw,pitch,dx,dy){return {yaw:yaw+dx*.006,pitch:Math.max(-1.15,Math.min(1.15,pitch-dy*.004))}}
export function reactionShape(id){return ({'rx-nitrile':2,'grignard-acid':3,'nitrile-acid':4,'oxidation-acid':4,'acid-chloride':3,'acid-ester':1,'acid-amide':1,'acid-alcohol':4,'hvz':2,'bromo-hydroxy':2})[id]||3}
export function blendShape(weights,target,dt){const f=1-Math.exp(-Math.min(dt,50)/230);return weights.map((v,i)=>v+((i===target-1?1:0)-v)*f)}
export function morphParticle(p,time,weights,morph,index=0){const az=Math.atan2(p[2],p[0]),lat=Math.asin(Math.max(-1,Math.min(1,p[1]))),seed=((index*16807+137)%65521)/65521,a=az+lat*.8+time*.17,tube=.25+.07*Math.sin(az*4+time),twist=lat*5+az+time*.23,lobe=.38+.65*Math.abs(Math.sin(lat*2)),vortex=az+p[1]*3.8+time*.24,r=.36+.62*Math.sqrt(Math.max(0,1-p[1]*p[1])),targets=[[(.65+tube*Math.cos(lat*Math.PI))*Math.cos(a),tube*Math.sin(lat*Math.PI)*2.1,(.65+tube*Math.cos(lat*Math.PI))*Math.sin(a)],[Math.cos(twist)*(.40+.25*seed),p[1]*1.17,Math.sin(twist)*(.40+.25*seed)],[p[0]*lobe,p[1]*1.12,p[2]*lobe],[Math.cos(vortex)*r,p[1]*(.85+.18*Math.sin(az*2+time)),Math.sin(vortex)*r]],base=particleSurface(p,time);return base.map((v,i)=>v*(1-morph)+targets.reduce((sum,t,j)=>sum+t[i]*weights[j],0)*morph)}
export function separateLabels(input,width,height){const nodes=input.map(n=>({...n}));for(let pass=0;pass<22;pass++){for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=b.x-a.x,dy=b.y-a.y,ox=(a.width+b.width)/2+5-Math.abs(dx),oy=(a.height+b.height)/2+5-Math.abs(dy);if(ox<=0||oy<=0||a.pinned&&b.pinned)continue;const wa=a.pinned?0:b.pinned?1:.5,wb=b.pinned?0:a.pinned?1:.5;if(ox<oy){const move=(ox+.2)*(dx===0?(i%2?1:-1):Math.sign(dx));a.x-=move*wa;b.x+=move*wb}else{const move=(oy+.2)*(dy===0?(j%2?1:-1):Math.sign(dy));a.y-=move*wa;b.y+=move*wb}}for(const n of nodes){if(n.pinned)continue;n.x=Math.max(n.width/2+6,Math.min(width-n.width/2-6,n.x));n.y=Math.max(n.height/2+8,Math.min(height-n.height/2-38,n.y))}}return nodes}

export function displaceParticle(engine,p,index,step){if(engine.reduced)return p;const state=engine.physics,k=index*4;let ox=state[k],oy=state[k+1],vx=state[k+2],vy=state[k+3];if(!engine.paused){const dx=engine.pointer.x-p.x-ox,dy=engine.pointer.y-p.y-oy,range=Math.max(90,engine.radius*.72),influence=engine.pointer.active?Math.exp(-(dx*dx+dy*dy)/(range*range))*(.38+.62*(p.z+1)/2):0,swirl=engine.pointer.energy*.0045;vx=(vx+(dx*.011*influence-dy*swirl*influence-ox*.038)*step)*Math.pow(.86,step);vy=(vy+(dy*.011*influence+dx*swirl*influence-oy*.038)*step)*Math.pow(.86,step);ox+=vx*step;oy+=vy*step;const length=Math.hypot(ox,oy),limit=engine.radius*.35;if(length>limit){ox*=limit/length;oy*=limit/length;vx*=.6;vy*=.6}state[k]=ox;state[k+1]=oy;state[k+2]=vx;state[k+3]=vy}return {...p,x:p.x+ox,y:p.y+oy}}
